import 'server-only';
import { siteConfig } from '@/data/siteConfig';

const trimSlash = (value: string) => value.replace(/\/+$/, '');
const isLocalHost = (value: string) => {
  try {
    return /^(localhost|127\.0\.0\.1|\[::1\])$/i.test(new URL(value).hostname);
  } catch {
    return false;
  }
};

/** The URL used for auth callbacks and links generated by server-side features. */
export function appUrl(): string {
  const canonical = trimSlash(siteConfig.url);
  const configured = process.env.NEXTAUTH_URL || process.env.SITE_URL;

  // Vercel's production domain is canonical. Ignore a stale localhost NEXTAUTH_URL
  // because NextAuth otherwise sends live users back to a developer machine.
  if (process.env.VERCEL_ENV === 'production') return canonical;
  if (configured && !(process.env.NODE_ENV === 'production' && isLocalHost(configured))) return trimSlash(configured);
  if (process.env.NODE_ENV === 'production') return canonical;
  return trimSlash(configured || 'http://localhost:3000');
}
